<section class="stats-grid">
<article class="stat-card"><div><p class="stat-label">Reportes disponibles</p><h2>6</h2><p class="stat-subtitle">Tipos de informe</p></div><i class="fa-solid fa-file-lines stat-icon"></i></article>
<article class="stat-card"><div><p class="stat-label">Última actualización</p><h2 class="medium-number">Hoy</h2><p class="stat-subtitle">Datos demostrativos</p></div><i class="fa-solid fa-clock stat-icon"></i></article>
<article class="stat-card"><div><p class="stat-label">Estado del sistema</p><h2>Normal</h2><p class="stat-subtitle">Sin alertas simuladas</p></div><i class="fa-solid fa-circle-check stat-icon green-text"></i></article>
<article class="stat-card"><div><p class="stat-label">Formato</p><h2>PDF / CSV</h2><p class="stat-subtitle">Vista de impresión disponible</p></div><i class="fa-solid fa-download stat-icon"></i></article>
</section>
<section class="report-grid">
<article class="panel report-card"><i class="fa-solid fa-microchip report-icon"></i><h2>Reporte de CPU y memoria</h2><p>Resumen del consumo de CPU, RAM, caché y memoria swap.</p><button class="btn btn-primary" data-report="CPU y memoria">Generar reporte</button></article>
<article class="panel report-card"><i class="fa-solid fa-list-check report-icon"></i><h2>Reporte de procesos</h2><p>Listado de procesos, PID, usuario, estado y consumo.</p><button class="btn btn-primary" data-report="Procesos">Generar reporte</button></article>
<article class="panel report-card"><i class="fa-solid fa-hard-drive report-icon"></i><h2>Reporte de almacenamiento</h2><p>Discos, particiones, espacio usado y espacio disponible.</p><button class="btn btn-primary" data-report="Almacenamiento">Generar reporte</button></article>
<article class="panel report-card"><i class="fa-solid fa-users report-icon"></i><h2>Reporte de usuarios</h2><p>Usuarios y grupos registrados en los datos de ejemplo.</p><button class="btn btn-primary" data-report="Usuarios y grupos">Generar reporte</button></article>
<article class="panel report-card"><i class="fa-solid fa-calendar-days report-icon"></i><h2>Reporte de planificación</h2><p>Algoritmos, diagrama de Gantt y métricas de ejecución.</p><button class="btn btn-primary" data-report="Planificación de CPU">Generar reporte</button></article>
<article class="panel report-card"><i class="fa-solid fa-diagram-project report-icon"></i><h2>Reporte de interbloqueos</h2><p>Estado del algoritmo del banquero y detección simulada.</p><button class="btn btn-primary" data-report="Interbloqueos">Generar reporte</button></article>
</section>
